(50, 'light', 5, '<div style=\"box-shadow:0 0 0 0 rgba(0,0,0,.2),0 0 0 0 rgba(0,0,0,.14),0 0 0 0 rgba(0,0,0,.12);color:#212121;border:1px solid rgba(0,0,0,.12);box-sizing:border-box;outline:0;display:inline-block;text-align:center;margin:0;min-width:64px;padding:0 16px;border-radius:4px;overflow:visible;background:0 0;font-size:14px;font-weight:400;line-height:34px\">Introduzir</div>'),
(51, 'light', 6, '<div style=\"box-shadow:0 0 0 0 rgba(0,0,0,.2),0 0 0 0 rgba(0,0,0,.14),0 0 0 0 rgba(0,0,0,.12);color:#b70505;border:1px solid rgba(0,0,0,.12);box-sizing:border-box;outline:0;display:inline-block;text-align:center;margin:0;min-width:64px;padding:0 16px;border-radius:4px;overflow:visible;background:0 0;font-size:14px;font-weight:400;line-height:34px\">Apagar</div>'),
(52, 'light', 7, '<div style=\"box-shadow:0 0 0 0 rgba(0,0,0,.2),0 0 0 0 rgba(0,0,0,.14),0 0 0 0 rgba(0,0,0,.12);color:rgba(0,0,0,.26);border:1px solid currentColor;box-sizing:border-box;outline:0;display:inline-block;text-align:center;margin:0;min-width:64px;padding:0 16px;border-radius:4px;overflow:visible;background:0 0;font-size:14px;font-weight:400;line-height:34px\">readonly/inativo</div>'),
(53, 'light', 8, '<div style=\"box-shadow:0 0 0 0 rgba(0,0,0,.2),0 0 0 0 rgba(0,0,0,.14),0 0 0 0 rgba(0,0,0,.12);color:#616161;border:1px solid rgba(0,0,0,.12);box-sizing:border-box;outline:0;display:inline-block;text-align:center;margin:0;min-width:64px;padding:0 16px;border-radius:4px;overflow:visible;background:0 0;font-size:14px;font-weight:400;line-height:34px\">Processar</div>'),
(54, 'light', 9, '<div style=\"box-shadow: 0 0 0 0 rgba(0,0,0,.2),0 0 0 0 rgba(0,0,0,.14),0 0 0 0 rgba(0,0,0,.12);background-color: rgba(0,0,0,.12);color: #fff !important;box-sizing: border-box;position: relative;-webkit-user-select: none;-moz-user-select: none;-ms-user-select: none;user-select: none;cursor: pointer;outline: none;border: none;-webkit-tap-highlight-color: transparent;display: inline-block;white-space: nowrap;text-decoration: none;vertical-align: baseline;text-align: center;margin: 0;min-width: 64px;line-height: 36px;padding: 0 16px;border-radius: 4px;overflow: visible;font-size: 14px;font-weight: 400;\">Processar</div>'),
(55, 'light', 10, '<div style=\"background-color: rgba(0,0,0,.12);color: rgba(0,0,0,.26);box-shadow: 0 0 0 0 rgba(0,0,0,.2),0 0 0 0 rgba(0,0,0,.14),0 0 0 0 rgba(0,0,0,.12);box-sizing: border-box;position: relative;-webkit-user-select: none;-moz-user-select: none;-ms-user-select: none;user-select: none;cursor: pointer;outline: none;border: none;-webkit-tap-highlight-color: transparent;display: inline-block;white-space: nowrap;text-decoration: none;vertical-align: baseline;text-align: center;margin: 0;min-width: 64px;line-height: 36px;padding: 0 16px;border-radius: 4px;overflow: visible;font-size: 14px;font-weight: 400;\">Processar</div>'),
(56, 'light', 11, '<div style=\"display:inline-flex;padding:7px 12px;border-radius:16px;align-items:center;min-height:32px;height:1px;border:none;-webkit-appearance:none;-moz-appearance:none;position:relative;box-sizing:border-box;font-size:14px;font-weight:500;white-space:nowrap;letter-spacing:normal;color:#fff;background-color:#139b25;\">Assinado</div>\"'),
(57, 'light', 12, '<div style=\"display:inline-flex;padding:7px 12px;border-radius:16px;align-items:center;min-height:32px;height:1px;border:none;-webkit-appearance:none;-moz-appearance:none;position:relative;box-sizing:border-box;font-size:14px;font-weight:500;white-space:nowrap;letter-spacing:normal;color:#fff;background-color:#ff8f00;\">Em edição</div>'),
(58, 'light', 13, '<div style=\"display:inline-flex;padding:7px 12px;border-radius:16px;align-items:center;min-height:32px;height:1px;border:none;-webkit-appearance:none;-moz-appearance:none;position:relative;box-sizing:border-box;font-size:14px;font-weight:500;white-space:nowrap;letter-spacing:normal;color:#fff;background-color:#b70505;\">Anulado</div>\"'),
(59, 'light', 14, '<div style=\"display:inline-flex;padding:7px 12px;border-radius:16px;align-items:center;min-height:32px;height:1px;border:none;-webkit-appearance:none;-moz-appearance:none;position:relative;box-sizing:border-box;font-size:14px;font-weight:500;white-space:nowrap;letter-spacing:normal;color:#fff;background-color:#707070;\">Rascunho</div>\"'),
