;border:solid 2px #fff;background-color:rgb(255, 225, 189);color:#000;padding:4px 20px;font-size:20px}</style>\r\n<table class=\"phcgo-new-table\" style=\"display: flex; justify-content: center;\"><tbody>\r\n<tr><td>Cabeçalho 1</td>\r\n<td>Cabeçalho 2</td></tr>\r\n<tr><td>Linha 1 Coluna 1</td>\r\n<td>Linha 1 Coluna 2</td></tr>\r\n<tr><td>Linha 2 Coluna 1</td>\r\n<td>Linha 2 Coluna 2</td></tr></tbody></table>\r\n\r\n<br>\r\n\r\n<!-- Estilos necessários para a tabela -->\r\n<style>.phcgo-new-table-blue>tbody>tr>td{border-radius:20px;border:solid 2px #fff;background-color:#f2f2f2;color:#000;padding:5px 20px}.phcgo-new-table-blue>tbody>tr:nth-child(1)>td{border-radius:20px;border:solid 2px #fff;background-color:#3fa8f6;color:#fff;padding:4px 20px;font-size:20px}</style>\r\n<table class=\"phcgo-new-table-blue\" style=\"display: flex; justify-content: center;\"><tbody>\r\n<tr><td>Cabeçalho 1</td>\r\n<td>Cabeçalho 2</td></tr>\r\n<tr><td>Linha 1 Coluna 1</td>\r\n<td>Linha 1 Coluna 2</td></tr>\r\n<tr><td>Linha 2 Coluna 1</td>\r\n<td>Linha 2 Coluna 2</td></tr></tbody></table>\r\n\r\n\r\n<hr style=\"border-top: 3px solid rgb(238, 238, 238);\">\r\n<br></div>\r\n<!-- Fim do Colapsável #5 -->\r\n<!-- Início do Colapsável #6 -->\r\n<div class=\"row seccao-phcgo\"><div class=\"col-xs-8\"><a href=\"#links\" data-toggle=\"collapse\"><h2 class=\"manuais\">Títulos Ligações</h2></a></div><div class=\"col-xs-4 text-right\"><a href=\"#links\" data-toggle=\"collapse\" style=\"display: block;\">Abrir/Fechar</a></div></div>\r\n\r\n<div id=\"links\" class=\"collapse multi-collapse\">\r\n\r\n<br>\r\n\r\n<h1 class=\"manuais\">Título/Heading 1</h1>\r\n<h2 class=\"manuais\">Título/Heading 2</h2>\r\n<h3 class=\"manuais\">Título/Heading 3</h3>\r\n<h1>Título/Heading 1</h1>\r\n<h2>Título/Heading 2</h2>\r\n<h3>Título/Heading 3</h3>\r\n\r\n\r\n<br>\r\n\r\n<a class=\"manuais\" href=\"#\" target=\"_blank\">Este é um link gerado</a>\r\n\r\n<br>\r\n\r\n<br></div>\r\n<!-- Fim do Colapsável #6 -->\r\n<!-- Início do Colapsável #7 -->\r\n<div class=\"row seccao-phcgo\"><div class=\"col-xs-8\"><a href=\"#vbnetapi\" data-toggle=\"collapse\"><h2 class=\"manuais\">Formatação código VB.NET</h2></a></div><div class=\"col-xs-4 text-right\"><a href=\"#vbnetapi\" data-toggle=\"collapse\" style=\"display: block;\">Abrir/Fechar</a></div></div>\r\n\r\n<div id=\"vbnetapi\" class=\"collapse multi-collapse\">\r\n<br>\r\n\r\n<!-- HTML generated using hilite.me --><div style=\"background: #272822; overflow:auto;width:auto;border:solid #eb8475;border-width:.1em .1em .1em .8em;padding:.2em .6em;\"><pre style=\"background:transparent;border:0px;margin: 0; line-height: 125%\"><span style=\"color: #75715e\">\" todas<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div> as bibliotecas devem estar dentro de uma \"Class\"</span><br>\r\n<span style=\"color: #66d9ef\">class</span> <span style=\"color: #a6e22e\">codpost</span><br>\r\n<br>\r\n<span style=\"color: #75715e\">\" função que vai retornar a localidade de um código postal</span><br>\r\n<span style=\"color: #66d9ef\">Public</span> <span style=\"color: #66d9ef\">shared</span> <span style=\"color: #66d9ef\">Function</span> <span style=\"color: #a6e22e\">codpost</span><span style=\"color: #f8f8f2\">(mcodpost</span> <span style=\"color: #f92672\">As</span> <span style=\"color: #66d9ef\">string</span><span style=\"color: #f8f8f2\">)</span> <span style=\"color: #f92672\">As</span> <span style=\"color: #66d9ef\">String</span><br>\r\n<br>\r\n<span style=\"color: #75715e\">\" variável com a localidade</span><br>\r\n<span style=\"color: #66d9ef\">Dim</span> <span style=\"color: #f8f8f2\">retval</span> <span style=\"color: #f92672\">As</span> <span style=\"color: #66d9ef\">string</span><span style=\"color: #f92672\">=</span><span style=\"color: #e6db74\">\"\"</span><br>\r\n<br>\r\n<span style=\"color: #75715e\">\" valida o tamonho do texto escrito, se já é um código postal com o tamanho certo. Pode ser 7 digitos seguidos ou 8 digitos com o traço a seguir aos 4 primeiros</span><br>\r\n<span style=\"color: #66d9ef\">If</span> <span style=\"color: #f8f8f2\">mcodpost.trim.length</span><span style=\"color: #f92672\">=</span><span style=\"color: #ae81ff\">7</span> <span style=\"color: #f92672\">And</span> <span style=\"color: #f8f8f2\">mcodpost.substring(</span><span style=\"color: #ae81ff\">4</span><span style=\"color: #f8f8f2\">,</span><span style=\"color: #ae81ff\">1</span><span style=\"color: #f8f8f2\">)</span><span style=\"color: #f92672\">&lt;&gt;</span><span style=\"color: #e6db74\">\"-\"</span><br>\r\n<span style=\"color: #f8f8f2\">mcodpost</span><span style=\"color: #f92672\">=</span><span style=\"color: #f8f8f2\">mcodpost.trim</span><br>\r\n<span style=\"color: #66d9ef\">Else</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #66d9ef\">If</span> <span style=\"color: #f8f8f2\">mcodpost.trim.length</span><span style=\"color: #f92672\">=</span><span style=\"color: #ae81ff\">8</span> <span style=\"color: #f92672\">And</span> <span style=\"color: #f8f8f2\">mcodpost.substring(</span><span style=\"color: #ae81ff\">4</span><span style=\"color: #f8f8f2\">,</span><span style=\"color: #ae81ff\">1</span><span style=\"color: #f8f8f2\">)</span><span style=\"color: #f92672\">=</span><span style=\"color: #e6db74\">\"-\"</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f8f8f2\">mcodpost</span><span style=\"color: #f92672\">=</span><span style=\"color: #f8f8f2\">mcodpost.substring(</span><span style=\"color: #ae81ff\">0</span><span style=\"color: #f8f8f2\">,</span><span style=\"color: #ae81ff\">4</span><span style=\"color: #f8f8f2\">)</span> <span style=\"color: #f8f8f2\">mcodpost.substring(</span><span style=\"color: #ae81ff\">5</span><span style=\"color: #f8f8f2\">,</span><span style=\"color: #ae81ff\">3</span><span style=\"color: #f8f8f2\">)</span><br>\r\n<span style=\"color: #66d9ef\">End</span> <span style=\"color: #66d9ef\">If</span><br>\r\n<span style=\"color: #66d9ef\">End</span> <span style=\"color: #66d9ef\">If</span><br>\r\n<br>\r\n<span style=\"color: #75715e\">\" vamos chamar a API de códigos postais PT API - https://www.duminio.com/ptcp/ para obter os dados do código introduzido</span><br>\r\n<span style=\"color: #66d9ef\">Dim</span> <span style=\"color: #f8f8f2\">url</span> <span style=\"color: #f92672\">=</span> <span style=\"color: #66d9ef\">String</span><span style=\"color: #f8f8f2\">.Format(</span><span style=\"color: #e6db74\">\"https://api.duminio.com/ptcp/v2/ptapi610813c4d15a62.33494622/\"</span> <span style=\"color: #f8f8f2\">mcodpost.trim)</span><br>\r\n<span style=\"color: #66d9ef\">Dim</span> <span style=\"color: #f8f8f2\">request</span>  <span style=\"color: #f92672\">As</span> <span style=\"color: #f8f8f2\">HttpWebRequest</span> <span style=\"color: #f92672\">=</span> <span style=\"color: #66d9ef\">CType</span><span style=\"color: #f8f8f2\">(WebRequest.Create(url),</span> <span style=\"color: #f8f8f2\">HttpWebRequest)</span><br>\r\n<span style=\"color: #f8f8f2\">request.Method</span> <span style=\"color: #f92672\">=</span> <span style=\"color: #f8f8f2\">WebRequestMethods.Http.Get</span><br>\r\n<span style=\"color: #f8f8f2\">request.ContentType</span> <span style=\"color: #f92672\">=</span> <span style=\"color: #e6db74\">\"application/x-www-form-urlencoded\"</span><br>\r\n<br>\r\n<span style=\"color: #75715e\">\"colocamos a resposta numa variável</span><br>\r\n<span style=\"color: #66d9ef\">Dim</span> <span style=\"color: #f8f8f2\">response</span>  <span style=\"color: #f92672\">As</span> <span style=\"color: #f8f8f2\">HttpWebResponse</span> <span style=\"color: #f92672\">=</span> <span style=\"color: #66d9ef\">DirectCast</span><span style=\"color: #f8f8f2\">(request.GetResponse(),</span> <span style=\"color: #f8f8f2\">HttpWebResponse)</span><br>\r\n<br>\r\n<span style=\"color: #66d9ef\">If</span> <span style=\"color: #f8f8f2\">response</span> <span style=\"color: #f92672\">IsNot</span> <span style=\"color: #66d9ef\">Nothing</span> <span style=\"color: #66d9ef\">Then</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #66d9ef\">Dim</span> <span style=\"color: #f8f8f2\">responseContent</span> <span style=\"color: #f92672\">=</span> <span style=\"color: #66d9ef\">New</span> <span style=\"color: #f8f8f2\">StreamReader(response.GetResponseStream()).ReadToEnd()</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #75715e\">\" se a resposta é curta significa que deu erro ou o código postal introduzido não foi encontrado</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #66d9ef\">If</span> <span style=\"color: #f8f8f2\">responseContent.tostring.length</span><span style=\"color: #f92672\">&lt;</span><span style=\"color: #ae81ff\">80</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f8f8f2\">retval</span><span style=\"color: #f92672\">=</span><span style=\"color: #e6db74\">\"ERR\"</span><br>\r\n<span style=\"color: #66d9ef\">Else</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #75715e\">\"se a resposta é válida, dado que a resposta é em JSON criamos um objeto, arrays de objetos, com todos os dados da resposta</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #66d9ef\">Dim</span> <span style=\"color: #f8f8f2\">webObj</span> <span style=\"color: #f92672\">=</span> <span style=\"color: #f8f8f2\">fastJSON.JSON.ToObject(</span><span style=\"color: #66d9ef\">Of</span> <span style=\"color: #66d9ef\">Object</span><span style=\"color: #f8f8f2\">)(responseContent)</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #66d9ef\">If</span> <span style=\"color: #f8f8f2\">webObj</span> <span style=\"color: #f92672\">IsNot</span> <span style=\"color: #66d9ef\">Nothing</span> <span style=\"color: #66d9ef\">Then</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #75715e\">\" da resposta retiramos o valor do item Localidade do primeiro objeto</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #66d9ef\">Dim</span> <span style=\"color: #f8f8f2\">local</span> <span style=\"color: #f92672\">=</span> <span style=\"color: #f8f8f2\">webObj(</span><span style=\"color: #ae81ff\">0</span><span style=\"color: #f8f8f2\">).item(</span><span style=\"color: #e6db74\">\"Localidade\"</span><span style=\"color: #f8f8f2\">)</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #66d9ef\">If</span> <span style=\"color: #f8f8f2\">local</span> <span style=\"color: #f92672\">IsNot</span> <span style=\"color: #66d9ef\">Nothing</span> <span style=\"color: #66d9ef\">Then</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f8f8f2\">retval</span><span style=\"color: #f92672\">=</span><span style=\"color: #f8f8f2\">local.tostring</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #66d9ef\">End</span> <span style=\"color: #66d9ef\">If</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #66d9ef\">End</span> <span style=\"color: #66d9ef\">If</span><br>\r\n<span style=\"color: #66d9ef\">End</span> <span style=\"color: #66d9ef\">If</span><br>\r\n<span style=\"color: #66d9ef\">End</span> <span style=\"color: #66d9ef\">If</span><br>\r\n<br>\r\n<span style=\"color: #66d9ef\">Return</span> <span style=\"color: #f8f8f2\">retval</span><br>\r\n<span style=\"color: #66d9ef\">End</span> <span style=\"color: #66d9ef\">Function</span><br>\r\n<span style=\"color: #66d9ef\">End</span> <span style=\"color: #66d9ef\">class</span><br>\r\n</pre></div><br>\r\n</div>\r\n<!-- Fim do Colapsável #7 -->\r\n<!-- Início do Colapsável #8 -->\r\n<div class=\"row seccao-phcgo\"><div class=\"col-xs-8\"><a href=\"#jsonapi\" data-toggle=\"collapse\"><h2 class=\"manuais\">Formatação código JSON</h2></a></div><div class=\"col-xs-4 text-right\"><a href=\"#jsonapi\" data-toggle=\"collapse\" style=\"display: block;\">Abrir/Fechar</a></div></div>\r\n\r\n<div id=\"jsonapi\" class=\"collapse multi-collapse\">\r\n\r\n<br>\r\n<!-- HTML generated using hilite.me --><div style=\"background: #272822; overflow:auto;width:auto;border:solid #eb8475;border-width:.1em .1em .1em .8em;padding:.2em .6em;\"><pre style=\"background:transparent;border:0px;margin: 0; line-height: 125%\"><span style=\"color: #f8f8f2\">{</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"customer\"</span><span style=\"color: #f8f8f2\">:{</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"number\"</span><span style=\"color: #f8f8f2\">:</span><span style=\"color: #ae81ff\">1</span><span style=\"color: #f8f8f2\">,</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"name\"</span><span style=\"color: #f8f8f2\">:</span><span style=\"color: #e6db74\">\"Test\"</span><span style=\"color: #f8f8f2\">,</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"address\"</span><span style=\"color: #f8f8f2\">:</span><span style=\"color: #e6db74\">\"Grand Boulevard 1\"</span><span style=\"color: #f8f8f2\">,</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"postalCode\"</span><span style=\"color: #f8f8f2\">:</span><span style=\"color: #e6db74\">\"1234-100\"</span><span style=\"color: #f8f8f2\">,</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"city\"</span><span style=\"color: #f8f8f2\">:</span><span style=\"color: #e6db74\">\"Town\"</span><span style=\"color: #f8f8f2\">,</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"country\"</span><span style=\"color: #f8f8f2\">:</span><span style=\"color: #e6db74\">\"UK\"</span><span style=\"color: #f8f8f2\">,</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"email\"</span><span style=\"color: #f8f8f2\">:</span><span style=\"color: #e6db74\">\"test@test.com\"</span><span style=\"color: #f8f8f2\">,</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"taxNumber\"</span><span style=\"color: #f8f8f2\">:</span><span style=\"color: #e6db74\">\"123456789\"</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f8f8f2\">},</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"requestOptions\"</span><span style=\"color: #f8f8f2\">:{</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"option\"</span><span style=\"color: #f8f8f2\">:</span><span style=\"color: #ae81ff\">1</span><span style=\"color: #f8f8f2\">,</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"requestedFields\"</span><span style=\"color: #f8f8f2\">:[</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #e6db74\">\"no\"</span><span style=\"color: #f8f8f2\">,</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #e6db74\">\"obranome\"</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f8f8f2\">],</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"reportName\"</span><span style=\"color: #f8f8f2\">:</span><span style=\"color: #e6db74\">\"Encomenda de Cliente Minimal\"</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f8f8f2\">},</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"internalDocument\"</span><span style=\"color: #f8f8f2\">:{</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"docType\"</span><span style=\"color: #f8f8f2\">:</span><span style=\"color: #ae81ff\">1</span><span style=\"color: #f8f8f2\">,</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"customerName\"</span><span style=\"color: #f8f8f2\">:</span><span style=\"color: #e6db74\">\"João\"</span><span style=\"color: #f8f8f2\">,</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"salesmanName\"</span><span style=\"color: #f8f8f2\">:</span><span style=\"color: #e6db74\">\"Gary\"</span><span style=\"color: #f8f8f2\">,</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"description\"</span><span style=\"color: #f8f8f2\">:</span><span style=\"color: #e6db74\">\"Order\"</span><span style=\"color: #f8f8f2\">,</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"issuingAddress1\"</span><span style=\"color: #f8f8f2\">:</span><span style=\"color: #e6db74\">\"Issue Address 1\"</span><span style=\"color: #f8f8f2\">,</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"issuingPostalCode\"</span><span style=\"color: #f8f8f2\">:</span><span style=\"color: #e6db74\">\"2010-152\"</span><span style=\"color: #f8f8f2\">,</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"issuingLocality\"</span><span style=\"color: #f8f8f2\">:</span><span style=\"color: #e6db74\">\"Issue locality\"</span><span style=\"color: #f8f8f2\">,</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"documentObservations\"</span><span style=\"color: #f8f8f2\">:</span><span style=\"color: #e6db74\">\"This is an observation\"</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f8f8f2\">},</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"products\"</span><span style=\"color: #f8f8f2\">:[</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f8f8f2\">{</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"reference\"</span><span style=\"color: #f8f8f2\">:</span><span style=\"color: #e6db74\">\"C021\"</span><span style=\"color: #f8f8f2\">,</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"designation\"</span><span style=\"color: #f8f8f2\">:</span><span style=\"color: #e6db74\">\"Test2\"</span><span style=\"color: #f8f8f2\">,</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"unitCode\"</span><span style=\"color: #f8f8f2\">:</span><span style=\"color: #e6db74\">\"M\"</span><span style=\"color: #f8f8f2\">,</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"unitPrice\"</span><span style=\"color: #f8f8f2\">:</span><span style=\"color: #ae81ff\">15.55</span><span style=\"color: #f8f8f2\">,</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"discount1\"</span><span style=\"color: #f8f8f2\">:</span><span style=\"color: #ae81ff\">20</span><span style=\"color: #f8f8f2\">,</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"discount2\"</span><span style=\"color: #f8f8f2\">:</span><span style=\"color: #ae81ff\">0</span><span style=\"color: #f8f8f2\">,</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"quantity\"</span><span style=\"color: #f8f8f2\">:</span><span style=\"color: #ae81ff\">1</span><span style=\"color: #f8f8f2\">,</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"taxIncluded\"</span><span style=\"color: #f8f8f2\">:</span><span style=\"color: #66d9ef\">true</span><span style=\"color: #f8f8f2\">,</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"taxPercentage\"</span><span style=\"color: #f8f8f2\">:</span><span style=\"color: #ae81ff\">23</span><span style=\"color: #f8f8f2\">,</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f92672\">\"taxRegion\"</span><span style=\"color: #f8f8f2\">:</span><span style=\"color: #e6db74\">\"PT\"</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f8f8f2\">}</span><br>\r\n<div style=\"display:inline-block;width:20px;\"></div><span style=\"color: #f8f8f2\">]</span><br>\r\n<span style=\"color: #f8f8f2\">}</span><br>\r\n</pre></div><br>\r\n</div>\r\n<!-- Fim do Colapsável #8 -->\r\n<!-- Início do Colapsável #9 -->\r\n<div class=\"row seccao-phcgo\"><div class=\"col-xs-8\"><a href=\"#typescriptapi\" data-toggle=\"collapse\"><h2 class=\"manuais\">Formatação código TypeScript</h2></a></div><div class=\"col-xs-4 text-right\"><a href=\"#typescriptapi\" data-toggle=\"collapse\" style=\"display: block;\">Abrir/Fechar</a></div></div>\r\n\r\n<div id=\"typescriptapi\" class=\"collapse multi-collapse\">\r\n<br>\r\n<!-- HTML generated using hilite.me --><div style=\"background: #272822; overflow:auto;width:auto;border:solid #eb8475;border-width:.1em .1em .1em .8em;padding:.2em .6em;\"><pre style=\"background:transparent;border:0px;margin: 0; line-height: 125%\"><span style=\"color: #66d9ef\">let</span> <span style=\"color: #a6e22e\">query</span> <span style=\"color: #f92672\">=</span> <span style=\"color: #66d9ef\">new</span> <span style=\"color: #a6e22e\">QueryVO</span><span style=\"color: #f8f8f2\">();</span><br>\r\n<span style=\"color: #a6e22e\">query</span><span style=\"color: #f8f8f2\">.</span><span style=\"color: #a6e22e\">entityName</span> <span style=\"color: #f92672\">=</span> <span style=\"color: #a6e22e\">TABLES</span><span style=\"color: #f8f8f2\">.</span><span style=\"color: #a6e22e\">TD</span><span style=\"color: #f8f8f2\">;</span><br>\r\n<span style=\"color: #a6e22e\">query</span><span style=\"color: #f8f8f2\">.</span><span style=\"color: #a6e22e\">SelectItems</span><span style=\"color: #f8f8f2\">.</span><span style=\"color: #a6e22e\">push</span><span style=\"color: #f8f8f2\">(</span><span style=\"color: #a6e22e\">FIELDS</span><span style=\"color: #f8f8f2\">.</span><span style=\"color: #a6e22e\">TD_NDOC</span><span style=\"color: #f8f8f2\">);</span><br>\r\n<span style=\"color: #a6e22e\">query</span><span style=\"color: #f8f8f2\">.</span><span style=\"color: #a6e22e\">SelectItems</span><span style=\"color: #f8f8f2\">.</span><span style=\"color: #a6e22e\">push</span><span style=\"color: #f8f8f2\">(</span><span style=\"color: #a6e22e\">FIELDS</span><span style=\"color: #f8f8f2\">.</span><span style=\"color: #a6e22e\">TD_NMDOC</span><span style=\"color: #f8f8f2\">);</span><br>\r\n<span style=\"color: #a6e22e\">query</span><span style=\"color: #f8f8f2\">.</span><span style=\"color: #a6e22e\">SelectItems</span><span style=\"color: #f8f8f2\">.</span><span style=\"color: #a6e22e\">push</span><span style=\"color: #f8f8f2\">(</span><span style=\"color: #a6e22e\">FIELDS</span><span style=\"color: #f8f8f2\">.</span><span style=\"color: #a6e22e\">TD_TIPOSAFT</span><span style=\"color: #f8f8f2\">);</span><br>\r\n<br>\r\n<span style=\"color: #66d9ef\">var</span> <span style=\"color: #a6e22e\">filter</span> <span style=\"color: #f92672\">=</span> <span style=\"color: #66d9ef\">new</span> <span style=\"color: #a6e22e\">FilterItem</span><span style=\"color: #f8f8f2\">();</span><br>\r\n<span style=\"color: #a6e22e\">filter</span><span style=\"color: #f8f8f2\">.</span><span style=\"color: #a6e22e\">filterItem</span> <span style=\"color: #f92672\">=</span> <span style=\"color: #a6e22e\">FIELDS</span><span style=\"color: #f8f8f2\">.</span><span style=\"color: #a6e22e\">TD_INACTIVO</span><span style=\"color: #f8f8f2\">;</span><br>\r\n<span style=\"color: #a6e22e\">filter</span><span style=\"color: #f8f8f2\">.</span><span style=\"color: #a6e22e\">comparison</span> <span style=\"color: #f92672\">=</span> <span style=\"color: #a6e22e\">Comparison</span><span style=\"color: #f8f8f2\">.</span><span style=\"color: #a6e22e\">EQUAL</span><span style=\"color: #f8f8f2\">;</span><br>\r\n<span style=\"color: #a6e22e\">filter</span><span style=\"color: #f8f8f2\">.</span><span style=\"color: #a6e22e\">valueItem</span> <span style=\"color: #f92672\">=</span> <span style=\"color: #ae81ff\">0</span><span style=\"color: #f8f8f2\">;</span><br>\r\n<span style=\"color: #a6e22e\">query</span><span style=\"color: #f8f8f2\">.</span><span styl